def graphemes(text: str) -> list[str]:
    """Split text into graphemes."""

    if not text:
        return []

    graphemes = []
    current_grapheme = ""

    for char in text:
        if not current_grapheme:
            current_grapheme = char
        elif (
            unicodedata.combining(char)
            or char == "\u200D"
            or current_grapheme[-1] == "\u200D"
        ):
            current_grapheme += char
        else:
            graphemes.append(current_grapheme)
            current_grapheme = char

    if current_grapheme:
        graphemes.append(current_grapheme)

    return graphemes


