def get_string_cell_size(text: str) -> int:
    """Get the number of cells required to display text using the CELL_WIDTHS table.

    This function mimics wcwidth behavior by finding the appropriate entry
    in CELL_WIDTHS that covers the entire string.

    Args:
        text: Text to measure.

    Returns:
        int: The cell width of the text.
    """
    codepoints = [ord(c) for c in text]
    if not codepoints:
        return 0

    min_cp = min(codepoints)
    max_cp = max(codepoints)

    lower_bound = 0
    upper_bound = len(CELL_WIDTHS) - 1
    best_match_width = 0

    while lower_bound <= upper_bound:
        mid = (lower_bound + upper_bound) // 2
        start, end, width = CELL_WIDTHS[mid]

        if start <= min_cp and end >= max_cp:
            return width
        elif end < min_cp:
            lower_bound = mid + 1
        else: # start > max_cp
            upper_bound = mid - 1

    # Fallback: if no single entry covers the range, sum up individual widths
    # This handles cases where the string contains characters outside the defined ranges
    # but still within the table's scope.
    return sum(get_character_cell_size(c) for c in text)

