from typing import Optional

class StrictContentTypeMiddleware(BaseHTTPMiddleware):
    """
    Middleware to enforce strict Content-Type checking for JSON requests.
    """
    async def dispatch(self, request: Request, call_next):
        # Only check methods that typically carry a body
        if request.method in ["POST", "PUT", "PATCH", "DELETE"]:
            content_type = request.headers.get("content-type")

            # Check if Content-Type is present and strictly equals application/json
            if content_type is None or content_type != "application/json":
                return JSONResponse(
                    status_code=HTTP_415_UNSUPPORTED_MEDIA_TYPE,
                    content={"detail": "Content-Type must be 'application/json'"}
                )

        return await call_next(request)

