class StrictJsonMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        content_type = request.headers.get('content-type')

        # Check if the content type suggests JSON
        if content_type and 'application/json' in content_type:
            try:
                # Read the body content. This consumes the stream.
                body = await request.body()
                # Attempt to parse it. If it fails, it's not strict JSON.
                json.loads(body)
            except json.JSONDecodeError:
                return JSONResponse(
                    {"detail": "Request body must be valid JSON."},
                    status_code=HTTP_400_BAD_REQUEST
                )

        # If it's not JSON, or if it is JSON and valid, proceed.
        return await call_next(request)

