def expand_scopes(scopes: List[str]) -> List[str]:
    """
    Expands a list of security scopes to include all hierarchical parent scopes.
    A scope is considered a parent of another if it is a prefix of the other,
    separated by colons (e.g., 'admin' is a parent of 'admin:users').
    """
    expanded = set(scopes)
    for scope in scopes:
        parts = scope.split(':')
        for i in range(1, len(parts)):
            parent_scope = ":".join(parts[:i])
            expanded.add(parent_scope)
    return list(expanded)

