def get_endpoint_context(dependant: Dependant, request_or_websocket: Any) -> Optional[str]:
    if dependant in ENDPOINT_CONTEXT_CACHE:
        return ENDPOINT_CONTEXT_CACHE[dependant]

    call = dependant.call
    if call is None:
        return None

    try:
        file = inspect.getfile(call)
        lines, start_line = inspect.getsourcelines(call)
        func_name = call.__name__
    except (TypeError, OSError):
        return None

    if hasattr(request_or_websocket, "method"):
        method = request_or_websocket.method
    else:
        method = "WS"

    route = dependant.path or ""

    context = f"  File \"{file}\", line {start_line}, in {func_name}\n    {method} {route}"
    ENDPOINT_CONTEXT_CACHE[dependant] = context
    return context


