    chain = []
    seen = set()

    def collect(obj):
        if obj is None or id(obj) in seen:
            return
        seen.add(id(obj))
        chain.append(obj)

        if hasattr(obj, "__wrapped__"):
            collect(obj.__wrapped__)
        if isinstance(obj, partial):
            collect(obj.func)
        if not inspect.isroutine(obj) and not inspect.isclass(obj):
            dunder_call = getattr(obj, "__call__", None)
            if dunder_call is not None:
                collect(dunder_call)

    collect(self.call)
    return chain

