            Measurement.get(console, options, self.renderable).maximum
            + self.left
            + self.right,
            options.max_width,
        )
    render_width = width - self.left - self.right
    if render_width < 0:
        count_options = options.update_width(1)
        count_lines = console.render_lines(self.renderable, count_options, style=style, pad=True)
        lines = [[] for _ in count_lines]
        actual_left = min(self.left, width)
        actual_right = width - actual_left
    else:
        render_options = options.update_width(render_width)
        if render_options.height is not None:
            render_options = render_options.update_height(
                height=render_options.height - self.top - self.bottom
            )
        lines = console.render_lines(
            self.renderable, render_options, style=style, pad=True
        )
        actual_left = self.left
        actual_right = self.right
    _Segment = Segment

    left = _Segment(" " * actual_left, style) if actual_left else None
    right = (
        [_Segment(f'{" " * actual_right}', style), _Segment.line()]
        if actual_right
        else [_Segment.line()]
    )
    blank_line: Optional[List[Segment]] = None
    if self.top:
        blank_line = [_Segment(f'{" " * width}\n', style)]
        yield from blank_line * self.top
    if left:
        for line in lines:
            yield left
            yield from line
            yield from right
    else:
        for line in lines:
            yield from line
            yield from right
    if self.bottom:
        blank_line = blank_line or [_Segment(f'{" " * width}\n', style)]
        yield from blank_line * self.bottom

