class ValidationException(Exception):
    def __init__(
        self,
        errors: Sequence[Any],
        file_path: str | None = None,
        line_number: int | None = None,
        function_name: str | None = None,
        http_method: str | None = None,
        route: str | None = None,
    ) -> None:
        super().__init__(f"Validation error: {errors}")
        self._errors = errors
        self.file_path = file_path
        self.line_number = line_number
        self.function_name = function_name
        self.http_method = http_method
        self.route = route

    def errors(self) -> Sequence[Any]:
        return self._errors

    def __str__(self) -> str:
        context = []
        if self.file_path:
            context.append(f'File "{self.file_path}", line {self.line_number}, in {self.function_name}')
        if self.http_method and self.route:
            context.append(f'{self.http_method} {self.route}')

        context_str = "\n".join(context)
        if context_str:
            return f"{super().__str__()}\n\n  {context_str}"
        return super().__str__()

