def should_bypass_proxies(url: str, no_proxy: str | None) -> bool:
    """Check whether the URL should bypass proxies based on the no_proxy list."""
    if not no_proxy:
        return False

    # Parse no_proxy list
    no_proxy_hosts = [h.strip() for h in no_proxy.split(',') if h.strip()]

    # Extract hostname from URL
    parsed_url = urlparse(url)
    host = parsed_url.hostname

    if not host:
        return False

    # Check if host matches any entry in no_proxy
    for entry in no_proxy_hosts:
        # 1. Check for IP/CIDR match (reusing existing logic)
        if is_valid_cidr(entry) and address_in_network(host, entry):
            return True

        # 2. Check for domain match (domain boundary constraint)
        # If entry is a domain (e.g., 'example.com')
        if '.' in entry and '/' not in entry and ':' not in entry:
            # Exact match
            if host == entry:
                return True
            # Subdomain match (e.g., 'www.example.com' matches 'example.com')
            if host.endswith('.' + entry):
                return True
            # Check if entry is a suffix of host (e.g., host='a.example.com', entry='example.com')
            if host.endswith(entry) and len(host) > len(entry) and host[len(host) - len(entry) - 1] == '.':
                return True

    return False

