class StrictContentTypeMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        # Only check for requests that might have a body
        if request.method in ("POST", "PUT", "PATCH"):
            content_type = request.headers.get("content-type")

            if content_type:
                # Check if the content type is JSON
                if "application/json" in content_type:
                    # Strict check: Content-Type must be exactly 'application/json'
                    # We split by semicolon to check for parameters (like charset)
                    parts = [p.strip() for p in content_type.split(';')]
                    primary_type = parts[0]

                    if primary_type != "application/json":
                        # Should not happen if "application/json" in content_type is true, but good safeguard
                        pass

                    # If there are parameters, we consider it non-strict and reject it.
                    if len(parts) > 1:
                        return JSONResponse(
                            status_code=415,
                            content={"detail": "Strict content type checking failed: Content-Type must be exactly application/json"},
                        )

        return await call_next(request)

