from starlette.requests import Request
from starlette.responses import JSONResponse
from fastapi.exceptions import HTTPException

class StrictJsonContentMiddleware(BaseHTTPMiddleware):
    """
    Enforces strict content type checking for JSON requests, only allowing
    'application/json' or 'application/json; charset=utf-8'.
    """
    async def dispatch(self, request: Request, call_next):
        content_type = request.headers.get("content-type")

        if content_type:
            # Check if the content type indicates JSON
            if "application/json" in content_type:
                # Strict check: only allow application/json or application/json; charset=utf-8
                if content_type != "application/json" and content_type != "application/json; charset=utf-8":
                    return JSONResponse(
                        status_code=415,
                        content={"detail": "Unsupported media type. Expected application/json or application/json; charset=utf-8."},
                    )

        return await call_next(request)

