def is_satisfied(self, granted_scopes: List[str]) -> bool:
    """
    Checks if the granted scopes satisfy the required scopes, respecting hierarchy.
    A granted scope G satisfies a required scope R if G == R, or if G is a parent of R.
    """
    for required_scope in self.scopes:
        is_satisfied = False
        for granted_scope in granted_scopes:
            if granted_scope == required_scope:
                is_satisfied = True
                break
            # Check for hierarchy: granted_scope is a prefix of required_scope
            # e.g., granted_scope="items", required_scope="items:read"
            if granted_scope.endswith(":") and required_scope.startswith(granted_scope + ":"):
                is_satisfied = True
                break
        if not is_satisfied:
            return False
    return True

