        scopes = security_requirement.scopes
        if security_name not in aggregated_scopes:
            aggregated_scopes[security_name] = set()
        aggregated_scopes[security_name].update(scopes)

    operation_security = []
    for name, scopes in aggregated_scopes.items():
        operation_security.append({name: list(scopes)})

    return security_definitions, operation_security

