def _parse_content_type_header(value):
    """
    Parses a Content-Type header value into a dictionary of parameters.

    Ignores malformed parameters that do not contain an '='.
    """
    content_type = {}
    if not value:
        return content_type

    # Split main type/subtype from parameters
    parts = value.split(';') # Simplified split for demonstration
    main_type = parts[0].strip()

    params = {}

    # Process parameters
    for part in parts[1:]:
        part = part.strip()
        if '=' in part:
            try:
                key, val = part.split('=', 1)
                params[key.strip()] = val.strip()
            except ValueError:
                # Should not happen if '=' is present
                pass
        # If '=' is not in part, it is ignored.

    return {
        'type': main_type,
        'params': params
    }

