class StrictJsonContentMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        content_type = request.headers.get("content-type")

        # Enforce strict content type checking for JSON requests
        if content_type:
            # Strict check: must be exactly 'application/json' with no parameters
            if content_type.strip() != "application/json":
                return JSONResponse(
                    {"detail": "Strict content type must be application/json"}, 
                    status_code=415
                )

        return await call_next(request)

