def include_router(self, other_router: "APIRouter", prefix: str | None = None, **kwargs) -> "APIRouter":
    """
    Include another APIRouter in this one, preserving instances.
    """
    if other_router is self:
        raise ValueError("Cannot include the same APIRouter instance into itself.")

    if prefix:
        prefix = f"{prefix}/{other_router.prefix}"

    for route in other_router.routes:
        # Preserve the instance instead of cloning/recreating it
        self.routes.append(route)
    return self

