def get_typed_signature(call: Callable[..., Any]) -> inspect.Signature:
    # Iteratively unwrap the callable to handle partial applications and decorators
    current_call = call
    while True:
        if isinstance(current_call, functools.partial):
            current_call = current_call.func
        elif inspect.isroutine(current_call):
            try:
                unwrapped = inspect.unwrap(current_call)
                if unwrapped is current_call:
                    break
                current_call = unwrapped
            except AttributeError:
                # Not a standard function/routine, stop unwrapping
                break
        else:
            # Not a partial or a routine, stop unwrapping
            break

    signature = inspect.signature(current_call)
    globalns = getattr(current_call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    typed_signature = inspect.Signature(typed_params)
    return typed_signature

def get_typed_return_annotation(call: Callable[..., Any]) -> Any:
    # Iteratively unwrap the callable to handle partial applications and decorators
    current_call = call
    while True:
        if isinstance(current_call, functools.partial):
            current_call = current_call.func
        elif inspect.isroutine(current_call):
            try:
                unwrapped = inspect.unwrap(current_call)
                if unwrapped is current_call:
                    break
                current_call = unwrapped
            except AttributeError:
                # Not a standard function/routine, stop unwrapping
                break
        else:
            # Not a partial or a routine, stop unwrapping
            break

    signature = inspect.signature(current_call)
    annotation = signature.return_annotation

    if annotation is inspect.Signature.empty:
        return None

    globalns = getattr(current_call, "__globals__", {})
    return get_typed_annotation(annotation, globalns)

