class StrictJSONContentTypeMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        content_type = request.headers.get("content-type")

        # Check if a content type is specified. If it is, it must be application/json.
        if content_type:
            # Check for strict match, ignoring parameters like charset
            if not content_type.strip().lower().startswith("application/json"):
                # Raise 415 Unsupported Media Type
                raise HTTPException(
                    status_code=415,
                    detail="Unsupported Media Type. Expected application/json."
                )

        return await call_next(request)

