from fastapi import FastAPI
from pydantic import BaseModel
import json

class ModelA(BaseModel):
    a: str

class ModelB(BaseModel):
    b: str

app = FastAPI(
    responses={
        500: {
            'model': ModelA | ModelB,
            'content': {"application/json": {
                'examples': {"Case A": {"value": "a"}}
            }}
        }
    }
)

@app.get('/route1')
def route1():
    return "test"

@app.get('/route2')
def route2():
    return "test"

@app.get('/route3')
def route3():
    return "test"

def test_issue():
    try:
        # Generate OpenAPI schema
        openapi_schema = app.openapi()

        # Check the 500 response for /route1
        response_500 = openapi_schema['paths']['/route1']['get']['responses']['500']

        # Extract anyOf array
        anyof_list = response_500['content']['application/json']['schema']['anyOf']

        # The correct behavior after the fix is that anyOf contains exactly one reference to ModelA and one to ModelB.
        # The buggy behavior duplicates these references.

        # Count unique references
        ref_counts = {}
        for ref in anyof_list:
            ref_name = ref['$ref'].split('/')[-1]
            ref_counts[ref_name] = ref_counts.get(ref_name, 0) + 1

        # Expected counts after fix: ModelA: 1, ModelB: 1
        expected_counts = {"ModelA": 1, "ModelB": 1}

        # Check if the actual counts match the expected counts (i.e., no duplication)
        actual_counts = {k: v for k, v in ref_counts.items()}

        assert actual_counts == expected_counts, f"Expected {expected_counts}, but got {actual_counts}"
        print("Issue resolved")

    except Exception as e:
        print("Other issues", repr(e))
        return

test_issue()

