def iter_graphemes(text: str) -> Iterable[str]:
    """Iterate over the graphemes of a string."""
    if not text:
        return

    start = 0
    for i, char in enumerate(text):
        if get_character_cell_size(char) > 0:
            if i > start:
                yield text[start:i]
            start = i
    yield text[start:]


def split_graphemes(text: str, cut: int) -> Tuple[str, str]:
    """Split a string into two at a given cell position, without splitting graphemes."""
    current_width = 0
    current_pos = 0
    for grapheme in iter_graphemes(text):
        g_width = cell_len(grapheme)
        if current_width + g_width > cut:
            return text[:current_pos], text[current_pos:]
        current_width += g_width
        current_pos += len(grapheme)
    return text, ""


